import * as path from 'path';
import { findLockfile } from '../src/core/lockfiles';
import { parseYarnClassicText } from '../src/core/lockfiles/yarn';
import { inventoryWithLockfile } from '../src/core/pipeline';
import { Dependency } from '../src/core/types';

/**
 * The same NestJS project installed with npm, pnpm 7/8/9, Yarn 1 and Yarn 4.
 * Every lockfile here was generated by the real package manager.
 */
const DIR = path.join(__dirname, 'fixtures/formats');
const FORMATS = {
  npm: 'npm',
  pnpm9: 'pnpm',
  pnpm8: 'pnpm',
  pnpm7: 'pnpm',
  'yarn-classic': 'yarn-classic',
  'yarn-berry': 'yarn-berry',
} as const;

const describeDep = (d: Dependency) => `${d.direct ? 'direct' : 'transitive'} ${d.dev ? 'dev' : 'prod'} ${d.reachable ?? '?'}`;
const summary = (deps: Dependency[]) =>
  Object.fromEntries(deps.map((d) => [`${d.name}@${d.version}`, describeDep(d)] as const).sort(([a], [b]) => a.localeCompare(b)));

/**
 * Per package name, the most exposed classification. Package managers dedupe
 * differently (yarn keeps path-to-regexp 8.3.0 and 8.4.2, npm only 8.3.0), so
 * exact versions may differ but what reaches production must not.
 */
const byName = (deps: Dependency[]) => {
  const out: Record<string, string> = {};
  for (const d of deps) {
    const cur = out[d.name];
    const mine = describeDep(d);
    if (!cur || (cur.includes(' dev') && mine.includes(' prod')) || (!cur.startsWith('direct') && mine.startsWith('direct'))) out[d.name] = mine;
  }
  return Object.fromEntries(Object.entries(out).sort(([a], [b]) => a.localeCompare(b)));
};

describe('lockfile formats', () => {
  let baseline: Record<string, string>;
  let baselineNames: Record<string, string>;
  beforeAll(async () => {
    const deps = (await inventoryWithLockfile(path.join(DIR, 'npm'))).dependencies;
    baseline = summary(deps);
    baselineNames = byName(deps);
  });

  it('npm baseline looks right', () => {
    expect(Object.keys(baseline).length).toBeGreaterThan(80);
    expect(baseline['@nestjs/core@11.1.17']).toBe('direct prod true');
    expect(baseline['@nestjs/platform-express@11.1.17']).toBe('direct prod true'); // loaded at runtime by @nestjs/core
    expect(baseline['multer@2.1.1']).toBe('transitive prod true');
    expect(baseline['handlebars@4.7.8']).toBe('direct dev false'); // direct, never imported
  });

  for (const [dir, format] of Object.entries(FORMATS)) {
    if (dir === 'npm') continue;
    it(`${dir}: detected as ${format}, same packages and classification as npm`, async () => {
      const { lockfile, dependencies } = await inventoryWithLockfile(path.join(DIR, dir));
      expect(lockfile.format).toBe(format);
      const names = byName(dependencies);
      // every package npm installed is there, classified the same way
      for (const [name, cls] of Object.entries(baselineNames)) expect([name, names[name]]).toEqual([name, cls]);
      // anything extra is only a different dedupe of a package npm also has... or a newer
      // transitive helper (get-intrinsic 1.3.1 pulls async-function): never a direct dependency
      for (const [name, cls] of Object.entries(names))
        if (!(name in baselineNames)) expect([name, cls.startsWith('direct')]).toEqual([name, false]);
    });
  }

  it('attack paths survive every format', async () => {
    for (const dir of Object.keys(FORMATS)) {
      const { dependencies } = await inventoryWithLockfile(path.join(DIR, dir));
      const multer = dependencies.find((d) => d.name === 'multer')!;
      expect([dir, multer.path]).toEqual([dir, ['@nestjs/core', '@nestjs/platform-express', 'multer']]);
    }
  });
});

describe('pnpm dev flags', () => {
  // pnpm 7/8 write their own dev: true/false per package; Argus derives dev from the graph instead
  it.each(['pnpm7', 'pnpm8'])('%s: graph-derived dev matches pnpm\'s own flags', async (dir) => {
    const YAML = (await import('yaml')).default;
    const fs = await import('fs');
    const lock = YAML.parse(fs.readFileSync(path.join(DIR, dir, 'pnpm-lock.yaml'), 'utf8'));
    const { dependencies } = await inventoryWithLockfile(path.join(DIR, dir));
    const ours = new Map(dependencies.map((d) => [`${d.name}@${d.version}`, d.dev]));
    let checked = 0;
    for (const [key, e] of Object.entries<{ dev?: boolean }>(lock.packages)) {
      if (typeof e.dev !== 'boolean') continue;
      const k = key.replace(/^\//, '');
      const [name, version] = dir === 'pnpm7'
        ? [k.slice(0, k.lastIndexOf('/')), k.slice(k.lastIndexOf('/') + 1).split('_')[0]]
        : [k.split('(')[0].slice(0, k.split('(')[0].indexOf('@', 1)), k.split('(')[0].slice(k.split('(')[0].indexOf('@', 1) + 1)];
      expect([`${name}@${version}`, ours.get(`${name}@${version}`)]).toEqual([`${name}@${version}`, e.dev]);
      checked++;
    }
    expect(checked).toBeGreaterThan(80);
  });
});

describe('lockfile detection', () => {
  it('returns null when there is no lockfile', () => {
    expect(findLockfile(__dirname)).toBeNull();
  });
});

describe('yarn classic text parser', () => {
  it('handles quoted scoped names, multiple descriptors and dependency blocks', () => {
    const entries = parseYarnClassicText(`# yarn lockfile v1


"@babel/code-frame@^7.0.0", "@babel/code-frame@^7.10.4":
  version "7.12.13"
  resolved "https://registry.yarnpkg.com/x"
  dependencies:
    "@babel/highlight" "^7.12.13"
  optionalDependencies:
    fsevents "~2.3.1"

lodash@^4.17.21:
  version "4.17.21"
`);
    expect(entries).toEqual([
      {
        descriptors: ['@babel/code-frame@^7.0.0', '@babel/code-frame@^7.10.4'],
        version: '7.12.13',
        dependencies: { '@babel/highlight': '^7.12.13' },
        optionalDependencies: { fsevents: '~2.3.1' },
      },
      { descriptors: ['lodash@^4.17.21'], version: '4.17.21', dependencies: {}, optionalDependencies: {} },
    ]);
  });
});

describe('monorepos (workspaces)', () => {
  // packages/api: express (+ nodemon dev) · packages/web: react (+ vite dev)
  it.each([
    ['npm', 'npm'],
    ['pnpm', 'pnpm'],
    ['yc', 'yarn-classic'],
    ['yb', 'yarn-berry'],
  ])('%s: dependencies of every workspace are direct, dev tools stay dev', async (dir, format) => {
    const { lockfile, dependencies } = await inventoryWithLockfile(path.join(__dirname, 'fixtures/workspaces', dir));
    expect(lockfile.format).toBe(format);
    const get = (n: string) => dependencies.find((d) => d.name === n);
    expect(get('express')).toMatchObject({ direct: true, dev: false, reachable: true });
    expect(get('react')).toMatchObject({ direct: true, dev: false, reachable: true });
    expect(get('nodemon')).toMatchObject({ direct: true, dev: true });
    expect(get('vite')).toMatchObject({ direct: true, dev: true });
    expect(get('body-parser')).toMatchObject({ direct: false, dev: false, reachable: true, path: ['express', 'body-parser'] });
  });
});
